{{ config(tags=["source_daad"]) }}

with source as (

    select * from {{ source('daad', 'funding_programmes') }}

),

records as (

    select
        payload as record,
        _batch_id::text as bronze_batch_id,
        _record_hash as bronze_record_hash,
        _landing_uri as bronze_landing_uri,
        _ingested_at as bronze_ingested_at
    from source

)

select
    (record ->> 'programme_id')::text as programme_id,
    (record ->> 'programme_slug')::text as programme_slug,
    (record ->> 'title')::text as title,
    (record ->> 'summary')::text as summary,
    (record ->> 'thematic_focus')::text as thematic_focus,
    (record ->> 'language')::text as language,
    (record ->> 'page_kind')::text as page_kind,
    (record ->> 'publish_date')::date as publish_date,
    (record ->> 'source_url')::text as source_url,
    (record ->> 'listing_url')::text as listing_url,
    bronze_batch_id,
    bronze_record_hash,
    bronze_landing_uri,
    bronze_ingested_at
from records
